int longestOnes(vector<int>& nums, int k) {
    int zeroCnt = 0, start = 0, ans = 0;
    for(int i = 0; i < nums.size(); i++) {
        if(nums[i] == 0)
            zeroCnt++;
        while(zeroCnt > k) {
            if(nums[start] == 0)
                zeroCnt--;
            start++;
        }
        if(zeroCnt <= k)
            ans = max(ans, i - start + 1);
    }
    return ans;
}

